window.HOEREN_TESTS[78] = {"id":"beim-fotografen","name":"Beim Fotografen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist das Fotostudio Licht. Ihre Familienfotos sind fertig — aber nicht alle sind gut geworden, und verloren sind sie nicht. Auf einigen hat ein Kind die Augen zu. Wir haben aber genug schöne. Kommen Sie vorbei und suchen Sie aus. Geöffnet bis 18 Uhr. Auf Wiederhören und bis bald!","gender":"f","q":"Was ist mit einigen Fotos?","opts":["Alle sind perfekt.","Sie sind verloren.","Auf einigen hat ein Kind die Augen zu."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Ich brauche dringend ein neues Bewerbungsfoto, nicht für den Pass und nicht für die Hochzeit. Mein altes ist zehn Jahre alt, da hatte ich noch Haare! Kennst du einen guten Fotografen? Es soll professionell aussehen, nicht so ein Automaten-Foto. Ruf zurück, ich habe nächste Woche ein Vorstellungsgespräch!","gender":"m","q":"Wofür braucht Markus ein Foto?","opts":["Für eine Bewerbung.","Für den Pass.","Für die Hochzeit."],"correct":0},{"transcript":"Achtung Kunden: Unser Fotostudio bietet ab Mai einen neuen Service. Wir digitalisieren Ihre alten Fotos und Dias. Wir machen nicht nur Pässe und verkaufen nicht nur Rahmen. So bleiben die Erinnerungen erhalten und gehen nicht kaputt. Pro hundert Fotos zahlen Sie 30 Euro. Bringen Sie die alten Bilder einfach vorbei. Wir freuen uns auf Ihren Besuch!","gender":"m","q":"Was ist der neue Service?","opts":["Pässe machen.","Alte Fotos digitalisieren.","Rahmen verkaufen."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hör mal, wir haben ein Baby-Fotoshooting gemacht, so süß, keine Hochzeit und kein Haustier! Der Fotograf war total geduldig, obwohl die Kleine ständig geweint hat. Die Fotos kommen in zwei Wochen. Ich schicke dir dann welche. Du kannst auch mal Fotos von deinen Kindern machen lassen. Bis bald!","gender":"f","q":"Von wem wurden Fotos gemacht?","opts":["Von einem Baby.","Von einer Hochzeit.","Von einem Haustier."],"correct":0},{"transcript":"Liebe Kunden: Im Sommer bieten wir Foto-Pakete für Hochzeiten an. Ein Fotograf begleitet Sie den ganzen Tag, von morgens bis zur Party, nicht nur eine Stunde und nicht nur die Party. Sie bekommen über dreihundert Fotos und ein schönes Album. Buchen Sie früh, die guten Termine sind schnell weg. Rufen Sie uns an für ein Angebot!","gender":"f","q":"Wie lange begleitet der Fotograf das Hochzeitspaar?","opts":["Nur eine Stunde.","Nur die Party.","Den ganzen Tag."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht welche Fotos? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Fotograf hat heute viele Termine. Hast du den Zettel für unsere Familie?"},{"speaker":"Lisa","gender":"f","text":"Er liegt auf dem Tisch. Fünf Leute wollen Bilder und jeder braucht etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Ich brauche ein Bewerbungsfoto, weil die Firma es morgen sehen will."},{"speaker":"Lisa","gender":"f","text":"Nimm ein weißes Hemd. Will jemand noch Urlaubsfotos vom Strand?"},{"speaker":"Lukas","gender":"m","text":"Urlaubsfotos braucht dieses Jahr keiner. Wir bleiben zu Hause."},{"speaker":"Lisa","gender":"f","text":"Ich selbst brauche Hochzeitsfotos im Park."},{"speaker":"Lukas","gender":"m","text":"Im Juni bei Sonne wird das schön. Was ist mit dem kleinen Kind von Tom?"},{"speaker":"Lisa","gender":"f","text":"Tom braucht Babyfotos. Das Kind ist erst drei Wochen alt."},{"speaker":"Lukas","gender":"m","text":"Macht jemand Naturfotos im Wald? Die Bäume sind gerade grün."},{"speaker":"Lisa","gender":"f","text":"Naturfotos macht diese Woche auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara fehlt auch noch auf dem Zettel."},{"speaker":"Lisa","gender":"f","text":"Sara braucht ein Passfoto für den neuen Ausweis. Das dauert nur ein paar Minuten."},{"speaker":"Lukas","gender":"m","text":"Das geht schnell hier im Laden. Tim kommt später mit dem Hund."},{"speaker":"Lisa","gender":"f","text":"Tim braucht Tierfotos. Der Hund rennt im Garten hinter einem Ball her."},{"speaker":"Lukas","gender":"m","text":"Das wird ein schönes Bild."},{"speaker":"Lisa","gender":"f","text":"Ich rufe den Fotografen jetzt an."}],"options":[{"letter":"a","text":"Hochzeitsfotos"},{"letter":"b","text":"Urlaubsfotos"},{"letter":"c","text":"Bewerbungsfoto"},{"letter":"d","text":"Babyfotos"},{"letter":"e","text":"Naturfotos"},{"letter":"f","text":"Tierfotos"},{"letter":"g","text":"Familienfotos"},{"letter":"h","text":"Passfoto"},{"letter":"i","text":"Porträtfotos"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"a"},{"person":"Tom","correct":"d"},{"person":"Sara","correct":"h"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet ein Passfoto? Bekomme ich es sofort, in fünf Minuten, oder dauert es eine Stunde oder einen Tag?"},{"speaker":"Fotograf","gender":"m","text":"Sechs Fotos für 15 Euro. Eine Stunde und einen Tag brauchen wir nicht."},{"speaker":"Kundin","gender":"f","text":"Bekomme ich sie sofort, in fünf Minuten?"},{"speaker":"Fotograf","gender":"m","text":"Ja, in fünf Minuten, nicht in einer Stunde und nicht an einem Tag."},{"speaker":"Kundin","gender":"f","text":"Perfekt, fünf Minuten. Dann warte ich hier. Danke."}],"q":"Wie lange dauert das Passfoto?","opts":["Eine Stunde.","Fünf Minuten.","Einen Tag."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, wann sind die Hochzeitsfotos fertig? In einer Woche oder sofort?"},{"speaker":"Fotografin","gender":"f","text":"In drei Wochen, nicht in einer Woche und nicht sofort."},{"speaker":"Mann","gender":"m","text":"So lange, drei Wochen? Nicht eine Woche?"},{"speaker":"Fotografin","gender":"f","text":"Ja, wir bearbeiten jedes Bild sorgfältig. Deshalb drei Wochen, nicht sofort."},{"speaker":"Mann","gender":"m","text":"Okay, drei Wochen. Dann warte ich. Danke für die Info."}],"q":"Wann sind die Hochzeitsfotos fertig?","opts":["In einer Woche.","Sofort.","In drei Wochen."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, können Sie das Foto heller machen? Kleiner muss es nicht, und unverändert bleibt es auch nicht."},{"speaker":"Fotograf","gender":"m","text":"Klar, heller machen am Computer ist kein Problem. Kleiner machen müssen wir nicht."},{"speaker":"Frau","gender":"f","text":"Und den Hintergrund ändern, oder nichts ändern?"},{"speaker":"Fotograf","gender":"m","text":"Auch heller und den Hintergrund, gegen Aufpreis. Ganz ohne Änderung geht es nicht."},{"speaker":"Frau","gender":"f","text":"Dann bitte heller machen. Kleiner nicht. Danke."}],"q":"Was möchte die Frau am Foto ändern?","opts":["Es kleiner machen.","Es heller machen.","Nichts."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Guten Tag, mein Sohn lacht nicht für das Foto. Er weint nicht und er ist nicht krank."},{"speaker":"Fotografin","gender":"f","text":"Kein Problem, ich kenne einen Trick. Weinen und krank ist er also nicht."},{"speaker":"Vater","gender":"m","text":"Welchen Trick, wenn er nicht lacht?"},{"speaker":"Fotografin","gender":"f","text":"Eine lustige Handpuppe, das klappt immer. Dann lacht er, ohne zu weinen."},{"speaker":"Vater","gender":"m","text":"Super, dann versuchen wir die Puppe. Er ist wirklich nicht krank. Danke."}],"q":"Was ist das Problem?","opts":["Der Sohn weint.","Der Sohn ist krank.","Der Sohn lacht nicht."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, drucken Sie die Fotos auch aus? Was kostet ein großer Abzug, 3 Euro oder 10 Euro?"},{"speaker":"Fotograf","gender":"m","text":"Ja, oder Sie bekommen sie digital. Nicht 3 Euro und nicht 10 Euro."},{"speaker":"Kunde","gender":"m","text":"Was kostet ein großer Abzug?"},{"speaker":"Fotograf","gender":"m","text":"Ein großer Abzug 5 Euro, nicht 3 und nicht 10."},{"speaker":"Kunde","gender":"m","text":"Dann drucken Sie einen großen für 5 Euro. Danke."}],"q":"Was kostet ein großer Abzug?","opts":["5 Euro.","3 Euro.","10 Euro."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Roth, einem Fotografen. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Roth, heute hat jeder eine Kamera im Handy. Braucht man da noch einen Fotografen?"},{"speaker":"Roth","gender":"m","text":"Ja, finde ich. Ein gutes Foto ist mehr als ein schnelles Bild. Licht, Moment und Gefühl muss man üben. Das Handy allein reicht oft nicht für wichtige Tage."},{"speaker":"Reporterin","gender":"f","text":"Was ist das Schwierigste an Ihrer Arbeit?"},{"speaker":"Roth","gender":"m","text":"Die Menschen zum Lächeln zu bringen. Viele sind vor der Kamera nervös. Ich rede dann einfach, bis sie vergessen, dass ich fotografiere. Das dauert ein paar Minuten."},{"speaker":"Reporterin","gender":"f","text":"Welche Aufträge mögen Sie am liebsten?"},{"speaker":"Roth","gender":"m","text":"Hochzeiten. Es ist der schönste Tag, und ich darf ihn festhalten. Die Leute sind glücklich, und ich arbeite gern in dieser Stimmung, von morgens bis abends."},{"speaker":"Reporterin","gender":"f","text":"Ändern Sie die Fotos viel am Computer?"},{"speaker":"Roth","gender":"m","text":"Nur ein bisschen. Die Menschen sollen echt aussehen, nicht wie in der Werbung. Ich mache das Licht schöner, aber das Gesicht bleibt normal. Stark ändern will ich nicht."},{"speaker":"Reporterin","gender":"f","text":"Was raten Sie Hobby-Fotografen?"},{"speaker":"Roth","gender":"m","text":"Achten Sie auf das Licht. Und machen Sie viele Bilder, dann ist ein gutes dabei. Üben Sie am Nachmittag am Fenster, das Licht ist weich. So lernt man schnell."}],"items":[{"q":"Herr Roth ändert seine Fotos sehr stark am Computer.","correct":"nein"},{"q":"Er findet, ein gutes Foto ist mehr als ein schnelles Bild.","correct":"ja"},{"q":"Viele Menschen sind vor der Kamera nervös.","correct":"ja"},{"q":"Er fotografiert am liebsten bei Hochzeiten.","correct":"ja"},{"q":"Er rät Hobby-Fotografen, nicht auf das Licht zu achten.","correct":"nein"}]}]};
